def transform(g):
    H,W=len(g),len(g[0])
    # connected 3-components (4-conn), bboxes
    seen=set(); boxes=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==3 and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    x,y=st.pop()
                    if (x,y) in seen: continue
                    seen.add((x,y)); comp.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        xx,yy=x+dx,y+dy
                        if 0<=xx<H and 0<=yy<W and g[xx][yy]==3: st.append((xx,yy))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                boxes.append((min(rs),max(rs),min(cs),max(cs)))
    centers={(r,c) for r in range(H) for c in range(W) if g[r][c]==2 and
             any(r0<=r<=r1 and c0<=c<=c1 for r0,r1,c0,c1 in boxes)}
    o=[row[:] for row in g]
    for r,c in centers:
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if dr==0 and dc==0: continue
                rr,cc=r+dr,c+dc
                if 0<=rr<H and 0<=cc<W and (rr,cc) not in centers: o[rr][cc]=1
    return o
